import numpy as np
from scipy.special import erf
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
C9=F['C9'].astype(np.float64); M9=F['M9'].astype(np.float64)
def gelu(z): return 0.5*z*(1+erf(z/np.sqrt(2)))
def stdz(X,tr): m=X[tr].mean(0); s=X[tr].std(0)+1e-6; return (X-m)/s
def ridge_W(Xtr,Y,lam):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0); n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return Wt, ym-xm@Wt
print('C9 per-dim std pct', np.percentile(C9.std(0),[1,50,99]), 'max', C9.std(0).max(), 'abs mean max', np.abs(C9.mean(0)).max())
print('C9 norm', np.percentile(np.linalg.norm(C9,axis=1),[1,50,99]))
cC=np.cov(C9.T); ec,Vc=np.linalg.eigh(cC)   # ascending
cM=np.cov(M9.T); em,Vm=np.linalg.eigh(cM); em=em[::-1]; Vm=Vm[:,::-1]
print('C9 eig asc', ec[:5], ec[380], ec[-5:]); print('M9 eig desc', em[:5], em[255], em[383])
def make_x(k,lam):
    Q=Vc[:,:k]; P=Vm[:,:k]; D=1/np.sqrt(em[:k])
    u=C9+lam*((M9-M9.mean(0))@P*D)@Q.T
    n=(u-u.mean(1,keepdims=True)); n/=n.std(1,keepdims=True); return n
def cv(X,lams,kern=None):
    res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f
            Xs=stdz(X,tr)
            if kern:
                b,t,wl=kern; Xn=Xs/np.linalg.norm(Xs,axis=1,keepdims=True)
                Z=np.concatenate([wl*Xs,gelu(b*(Xn@Xn[tr].T)-t)],1)
            else: Z=Xs
            Y=np.eye(8)[y[tr]]-1/8
            for l in lams:
                Wt,bb=ridge_W(Z[tr],Y,l); res[l]+=((Z[te]@Wt+bb).argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
for k in [192,384]:
    for lam in [0.1,0.3,1.0]:
        X=make_x(k,lam)
        print(k,lam,'lin',cv(X,[100,300,1000]))
